# The page. Built once, when the app starts.

# The sidebar picker reads as a plain list of design names, not a set of radio
# buttons. The control underneath stays a radio group, which is what gives one
# selection per family for free, without a reactiveVal and an observer per
# design to track which name was last clicked.
#
# The input is moved out of sight rather than removed with display:none, so it
# keeps keyboard focus and stays readable to a screen reader; :focus-visible
# puts the ring back, on the label.
#
# Written as Sass rather than plain CSS so the colours follow the theme: swap
# the bootswatch preset and the highlight follows it.
#
# When editing these rules, hard-reload the browser. bslib serves the compiled
# theme at bootstrap-<version>/bootstrap.min.css, named for the Bootstrap
# version rather than content-hashed, so the URL does not change when the Sass
# does and a cached copy will be served instead.
PICKER_RULES <- "
.design-picker .radio { margin: 0; }

.design-picker label {
  display: block;
  width: 100%;
  margin: 0;
  font-weight: 400;
  cursor: pointer;
}

.design-picker input[type='radio'] {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: 0;
  opacity: 0;
}

.design-picker label > span {
  display: block;
  padding: .3rem .6rem;
  border-radius: .25rem;
}

.design-picker label:hover input:not(:checked) + span {
  background: rgba($black, .06);
}

.design-picker input:checked + span {
  background: $primary;
  color: color-contrast($primary);
}

.design-picker input:focus-visible + span {
  outline: 2px solid $primary;
  outline-offset: 2px;
}
"

app_theme <- function() {
  bslib::bs_add_rules(bslib::bs_theme(bootswatch = "yeti"), PICKER_RULES)
}

app_ui <- function() {
  bslib::page_sidebar(
    title = "Experimental Designs",
    theme = app_theme(),
    fillable = FALSE,
    sidebar = bslib::sidebar(width = 300, picker_ui("picker")),
    bslib::card(
      bslib::card_header("Options"),
      # Filled by the selected design's module UI.
      shiny::uiOutput("options"),
      shiny::checkboxInput("randomize", "Randomize run order", value = FALSE)
    ),
    bslib::card(
      bslib::card_header("Design"),
      shiny::uiOutput("summary"),
      reactable::reactableOutput("table"),
      shiny::downloadButton("download", "Download CSV", class = "btn-sm mt-2")
    )
  )
}

# Space-filling designs. Two of them, because they disagree about what the
# user gets to choose:
#
# - Optimized designs are precomputed and looked up in the sfd package. Four
#   types up to ten factors, and uniform alone from eleven to fifteen, each
#   available only at particular run counts.
# - Random designs are unconstrained Latin hypercubes from DiceDesign. Almost
#   any number of factors and runs, and no type to choose.
#
# That difference is why they are two registry entries rather than one design
# with a type: switching between them changes which inputs are on screen, not
# just what a generator does with them.
#
# Pure computation: no Shiny here.

# ---- Shared ------------------------------------------------------------------

# What sfd holds, summarised once when Shiny sources this file: a list indexed
# from two factors up, each element naming the run counts every type offers at
# that many factors. Scanning all fourteen tables takes about a tenth of a
# second, which is worth paying once rather than on every keystroke.
SFD_SUPPORT <- lapply(seq_along(sfd::sfd_lib), function(i) {
  designs <- sfd::sfd_lib[[i]]
  lapply(split(designs$num_points, designs$type), function(x) sort(unique(x)))
})

# The package's type ids, and the labels we show for them. One map, read in
# both directions, so a new type in a future sfd version shows up as a missing
# label rather than silently as an id.
SFD_TYPE_LABELS <- c(
  audze_eglais = "Audze-Eglais",
  max_min_l1 = "Max-Min (L1)",
  max_min_l2 = "Max-Min (L2)",
  uniform = "Uniform"
)

# Which types belong to which design. The three criteria below optimise a
# Latin hypercube; a uniform design is built to a different criterion and is
# not an LHC at all, so it is a design of its own rather than a type within
# one.
#
# They differ in reach as well as in kind: the LHC criteria exist for 2 to 10
# factors, uniform for 2 to 15. One entry covering both would have to claim
# the wider range and then fail on most of it.
SFD_LHC_TYPES <- c("audze_eglais", "max_min_l1", "max_min_l2")
SFD_UNIFORM_TYPES <- "uniform"

sfd_labels <- function(ids) {
  unname(SFD_TYPE_LABELS[ids])
}

# Returns: a named list of the run counts each of `types` offers at this many
# factors, keyed by the package's type ids. Types with nothing here are left
# out, so the result can be empty.
sfd_list <- function(num_factors, types = names(SFD_TYPE_LABELS)) {
  index <- num_factors - 1
  if (index < 1 || index > length(SFD_SUPPORT)) {
    return(list())
  }
  available <- SFD_SUPPORT[[index]]
  available[intersect(types, names(available))]
}

# Returns: c(min, max) of the factor counts where any of `types` has a design.
# Derived rather than written down, so it follows the installed sfd.
sfd_factor_range <- function(types) {
  covered <- which(vapply(
    SFD_SUPPORT,
    function(available) any(types %in% names(available)),
    logical(1)
  ))
  range(covered) + 1L
}

# Build the table for one sfd design. Shared, because the optimized and
# uniform designs differ in which types they offer, not in how they are built.
sfd_table <- function(num_factors, num_runs, type, factor_names) {
  points <- sfd::get_design(num_factors, num_runs, type)
  # sfd returns integer levels 1 to num_runs; rescale to [0, 1] so these read
  # on the same scale as the random design.
  #
  # Divided by num_runs rather than each column's own maximum: every column is
  # a permutation of 1 to n so the two agree today, but the per-column version
  # would silently rescale each factor differently if that ever stopped
  # holding.
  table <- tibble::as_tibble(points)
  table[] <- lapply(table, function(level) (level - 1) / (num_runs - 1))
  names(table) <- factor_names
  table
}

# Validate the options shared by both sfd designs, then build. `types` is the
# set this design offers.
sfd_create <- function(num_factors, num_runs, type, factor_names, types) {
  limits <- sfd_factor_range(types)
  stop_unless(
    length(num_factors) == 1 &&
      !is.na(num_factors) &&
      num_factors == round(num_factors),
    "Number of factors must be a whole number."
  )
  if (num_factors < limits[1] || num_factors > limits[2]) {
    stop_out_of_range(num_factors, limits, "Number of factors")
  }

  available_types <- sfd_list(num_factors, types)
  if (!type %in% names(available_types)) {
    stop_unavailable(
      type,
      stats::setNames(
        names(available_types),
        sfd_labels(names(available_types))
      ),
      "design",
      sprintf("%d factors", num_factors)
    )
  }

  available_runs <- as.numeric(available_types[[type]])
  if (!num_runs %in% available_runs) {
    stop_unavailable(
      num_runs,
      available_runs,
      "run count",
      sprintf("%s in %d factors", sfd_labels(type), num_factors)
    )
  }
  stop_unless(
    length(factor_names) == num_factors,
    sprintf(
      "Give %d factor names, not %d.",
      num_factors,
      length(factor_names)
    )
  )

  sfd_table(num_factors, num_runs, type, factor_names)
}

# ---- Optimized Latin hypercubes (sfd) ----------------------------------------

# Returns: an unnamed character vector of package names.
spacefilling_opt_get_packages <- function() {
  "sfd"
}

# Returns: a named list of integer c(min, max) pairs.
spacefilling_opt_get_limits <- function() {
  list(num_factors = sfd_factor_range(SFD_LHC_TYPES))
}

# Returns: a character vector of sfd type ids named by display label, empty
# when this factor count has none.
spacefilling_opt_get_types <- function(num_factors) {
  ids <- names(sfd_list(num_factors, SFD_LHC_TYPES))
  stats::setNames(ids, sfd_labels(ids))
}

# Returns: a numeric vector of run counts, ascending, unnamed.
#
# Depends on the type as well as the factor count, because the criteria do not
# cover the same sizes: at six factors Max-Min (L1) offers four run counts and
# Audze-Eglais offers ninety-nine.
spacefilling_opt_get_num_runs_choices <- function(num_factors, type) {
  available <- sfd_list(num_factors, SFD_LHC_TYPES)
  if (length(type) != 1 || is.na(type) || !type %in% names(available)) {
    return(numeric(0))
  }
  as.numeric(available[[type]])
}

# Returns: a doe_design.
spacefilling_opt_create <- function(
  num_factors,
  num_runs,
  type,
  factor_names = default_factor_names(
    num_factors
  )
) {
  types <- spacefilling_opt_get_types(num_factors)
  if (is.null(type)) {
    type <- unname(types[1])
  }
  table <- sfd_create(
    num_factors,
    num_runs,
    type,
    factor_names,
    SFD_LHC_TYPES
  )
  new_design(
    table,
    sprintf(
      "%s Latin hypercube \u2013 %d factors, %d runs",
      sfd_labels(type),
      num_factors,
      num_runs
    ),
    sprintf(
      "Precomputed by the sfd package, %d levels rescaled to 0-1.",
      num_runs
    )
  )
}

# Returns: an unnamed character vector of notes, or character(0).
#
# The notes are built in _create(), since sfd returns a bare table with no
# metadata attached.
spacefilling_opt_get_notes <- function(design) {
  character(0)
}

# ---- Uniform designs (sfd) ---------------------------------------------------
#
# A uniform design minimises discrepancy from a uniform distribution over the
# region. That is a different criterion from the Latin hypercube ones above,
# and the result is not an LHC, so it is a design in its own right rather than
# a type within one. It also reaches further: 2 to 15 factors against 2 to 10.

# Returns: an unnamed character vector of package names.
spacefilling_unif_get_packages <- function() {
  "sfd"
}

# Returns: a named list of integer c(min, max) pairs.
spacefilling_unif_get_limits <- function() {
  list(num_factors = sfd_factor_range(SFD_UNIFORM_TYPES))
}

# Returns: an empty character vector. There is a single criterion here, so
# there is nothing to choose between.
spacefilling_unif_get_types <- function(...) {
  stats::setNames(character(0), character(0))
}

# Returns: a numeric vector of run counts, ascending, unnamed.
spacefilling_unif_get_num_runs_choices <- function(num_factors) {
  available <- sfd_list(num_factors, SFD_UNIFORM_TYPES)
  if (length(available) == 0) {
    return(numeric(0))
  }
  as.numeric(available[[SFD_UNIFORM_TYPES]])
}

# Returns: a doe_design. No type argument: there is only one.
spacefilling_unif_create <- function(
  num_factors,
  num_runs,
  factor_names = default_factor_names(
    num_factors
  )
) {
  table <- sfd_create(
    num_factors,
    num_runs,
    SFD_UNIFORM_TYPES,
    factor_names,
    SFD_UNIFORM_TYPES
  )
  new_design(
    table,
    sprintf(
      "Uniform design \u2013 %d factors, %d runs",
      num_factors,
      num_runs
    ),
    sprintf(
      "Precomputed by the sfd package, %d levels rescaled to 0-1.",
      num_runs
    )
  )
}

# Returns: an unnamed character vector of notes, or character(0).
spacefilling_unif_get_notes <- function(design) {
  character(0)
}

# ---- Random (DiceDesign) -----------------------------------------------------

# A practical ceiling of ours, not one of DiceDesign, which will build almost
# anything. Kept here because it belongs to this design.
RANDOM_LHC_MAX_FACTORS <- 50L
RANDOM_LHC_MAX_RUNS <- 1000L

# Returns: an unnamed character vector of package names.
spacefilling_rand_get_packages <- function() {
  "DiceDesign"
}

# Returns: a named list of integer c(min, max) pairs. Two axes here, because
# the run count is chosen rather than derived.
spacefilling_rand_get_limits <- function() {
  list(
    num_factors = c(2L, RANDOM_LHC_MAX_FACTORS),
    num_runs = c(2L, RANDOM_LHC_MAX_RUNS)
  )
}

# Returns: an empty character vector. There is nothing to choose between.
spacefilling_rand_get_types <- function(...) {
  stats::setNames(character(0), character(0))
}

# Returns: a doe_design. Coded from 0 to 1, as DiceDesign produces it.
spacefilling_rand_create <- function(
  num_factors,
  num_runs,
  seed = 1,
  factor_names = default_factor_names(
    num_factors
  )
) {
  limits <- spacefilling_rand_get_limits()
  stop_unless(
    length(num_factors) == 1 &&
      !is.na(num_factors) &&
      num_factors == round(num_factors),
    "Number of factors must be a whole number."
  )
  if (
    num_factors < limits$num_factors[1] || num_factors > limits$num_factors[2]
  ) {
    stop_out_of_range(num_factors, limits$num_factors, "Number of factors")
  }
  stop_unless(
    length(num_runs) == 1 && !is.na(num_runs) && num_runs == round(num_runs),
    "Number of runs must be a whole number."
  )
  if (num_runs < limits$num_runs[1] || num_runs > limits$num_runs[2]) {
    stop_out_of_range(num_runs, limits$num_runs, "Number of runs")
  }
  stop_unless(
    length(factor_names) == num_factors,
    sprintf(
      "Give %d factor names, not %d.",
      num_factors,
      length(factor_names)
    )
  )

  # seed is passed to DiceDesign rather than wrapped in set.seed() here, so the
  # caller's random state is left alone.
  built <- DiceDesign::lhsDesign(
    n = num_runs,
    dimension = num_factors,
    seed = seed
  )
  table <- tibble::as_tibble(built$design, .name_repair = "minimal")
  names(table) <- factor_names

  new_design(
    table,
    sprintf(
      "Random Latin hypercube – %d factors, %d runs",
      num_factors,
      num_runs
    ),
    sprintf("Coded from 0 to 1. Seed %d.", seed)
  )
}

# Returns: an unnamed character vector of notes, or character(0).
spacefilling_rand_get_notes <- function(design) {
  character(0)
}

test_that("names0 zero-pads only once the width demands it", {
  expect_equal(names0(3), c("x1", "x2", "x3"))
  expect_equal(names0(10)[c(1, 10)], c("x01", "x10"))
  expect_equal(names0(100)[c(1, 100)], c("x001", "x100"))
  expect_equal(names0(2, prefix = "C"), c("C1", "C2"))
})

test_that("factor_labels uses letters until they run out, then names0", {
  expect_equal(default_factor_names(3), c("A", "B", "C"))
  expect_equal(default_factor_names(26)[26], "Z")
  # One past the alphabet every label switches over, rather than mixing the
  # two schemes within one design.
  expect_equal(default_factor_names(27)[1:2], c("x01", "x02"))
  expect_equal(default_factor_names(27)[27], "x27")
  expect_false("A" %in% default_factor_names(27))
  expect_equal(default_factor_names(100)[1], "x001")
})

test_that("parse_factor_names fills, trims, truncates, and deduplicates", {
  expect_snapshot({
    rename_factors(NULL, 3)
    rename_factors("", 3)
    rename_factors("Temp, Pressure, Time", 3)
    rename_factors("  Temp ,   Pressure  ", 3)
    rename_factors("Temp, Pressure, Time, Catalyst, Speed", 3)
    rename_factors("Temp, Temp, Temp", 3)
    rename_factors(", ,Temp", 3)
  })
})

test_that("with_run_order adds the order columns without moving rows", {
  design <- new_design(data.frame(A = c(-1, 1), B = c(-1, -1)), "Two runs")
  expect_snapshot(with_run_order(design, randomize = FALSE)$table)
})

test_that("randomizing permutes the run order and nothing else", {
  design <- new_design(
    data.frame(A = c(-1, 1, -1, 1), B = c(-1, -1, 1, 1)),
    "Four runs"
  )
  withr::with_seed(42, {
    randomized <- with_run_order(design, randomize = TRUE)
  })
  expect_equal(randomized$table[["Standard order"]], 1:4)
  expect_setequal(randomized$table[["Run order"]], 1:4)
  # The design columns are untouched.
  expect_equal(randomized$table[c("A", "B")], design$table)
})

test_that("center_point_text pluralises and counts the total", {
  expect_snapshot({
    center_point_text(0, 2)
    center_point_text(1, 3)
    center_point_text(3, 5)
  })
})

test_that("display_table leaves coded levels and the order columns alone", {
  design <- new_design(data.frame(A = c(-1, 0, 1), B = c(1, 0, -1)), "Coded")
  shown <- display_table(with_run_order(design, randomize = FALSE))
  # Nothing is turned into text, and -1 stays -1 rather than becoming -1.000.
  expect_true(all(vapply(shown, is.numeric, logical(1))))
  expect_snapshot(shown)
})

test_that("display_table rounds to three significant figures, not decimals", {
  design <- new_design(
    data.frame(
      x1 = c(0.333333, 0.000123456),
      x2 = c(1234.567, 1.681793)
    ),
    "Mixed magnitudes"
  )
  shown <- display_table(design)
  # Significant figures, so a small value keeps its precision and a large one
  # is rounded in its leading digits. colFormat(digits = ) could do neither.
  expect_equal(shown$x1, c(0.333, 0.000123))
  expect_equal(shown$x2, c(1230, 1.68))
  expect_snapshot(shown)
})

test_that("the order columns are never rounded", {
  design <- new_design(data.frame(x1 = c(-1, 1)), "Two runs")
  shown <- display_table(with_run_order(design, randomize = FALSE))
  expect_equal(shown[["Standard order"]], 1:2)
  expect_equal(shown[["Run order"]], 1:2)
})

test_that("a design prints its title, notes, and table", {
  design <- new_design(
    data.frame(A = c(-1, 1)),
    "A tiny design",
    notes = "Defining relation: I = AB"
  )
  expect_snapshot(design)
})

test_that("stop_unless reports the message it was given", {
  expect_snapshot(
    error = TRUE,
    stop_unless(FALSE, "Choose between 2 and 8 factors.")
  )
  expect_true(stop_unless(TRUE, "unused"))
})

test_that("factor names may be separated by newlines as well as commas", {
  # The input is a text area, so one name per line is a natural thing to type.
  expect_equal(
    rename_factors("Temp\nPressure\nTime", 3),
    c("Temp", "Pressure", "Time")
  )
  expect_equal(
    rename_factors("Temp, Pressure\nTime", 3),
    c("Temp", "Pressure", "Time")
  )
  # Blank lines are dropped, like empty comma fields.
  expect_equal(
    rename_factors("Temp\n\nPressure", 3),
    c("Temp", "Pressure", "C")
  )
})

test_that("run_choices reports what the catalog actually holds", {
  expect_snapshot({
    factorial_get_num_runs_choices(2)
    factorial_get_num_runs_choices(3)
    factorial_get_num_runs_choices(6)
  })
})

test_that("the supported range is derived from FrF2, not declared", {
  catalogued <- as.integer(names(factorial_support))
  expect_equal(factorial_factor_range[2], max(catalogued))
  # Every offered run count is one FrF2 can actually build.
  for (k in c(3, 6, 12, 34)) {
    offered <- unname(factorial_get_num_runs_choices(k))
    expect_true(all(offered <= FACTORIAL_MAX_RUNS))
    expect_true(all(offered %in% c(factorial_support[[as.character(k)]], 2^k)))
  }
})

test_that("run_choices never offers a run count FrF2 lacks", {
  # The catalog is irregular: 34 factors has 2048 runs but not 1024. Deriving
  # the choices rather than computing a span of powers of two is what keeps a
  # missing size out of the dropdown.
  expect_false(1024 %in% factorial_get_num_runs_choices(34))
  expect_false(1024 %in% factorial_support[["34"]])
  expect_true(
    2048 %in%
      vapply(
        Filter(function(e) e$nfac == 34, FrF2::catlg),
        function(e) e$nruns,
        numeric(1)
      )
  )
})

test_that("nothing beyond the run ceiling is offered", {
  for (k in c(2, 8, 20, 60, factorial_factor_range[2])) {
    expect_true(all(
      unname(factorial_get_num_runs_choices(k)) <= FACTORIAL_MAX_RUNS
    ))
  }
})

test_that("catalog_entries finds fractions and skips full factorials", {
  # A full factorial is not in FrF2's catalog.
  expect_length(factorial_catalog_entries(3, 8), 0)
  # Several equivalent fractions exist at this size; the app offers a choice.
  expect_gt(length(factorial_catalog_entries(6, 16)), 1)
  # Best first: resolution never increases down the list.
  resolutions <- vapply(
    factorial_catalog_entries(6, 16),
    function(e) e$res,
    numeric(1)
  )
  expect_false(is.unsorted(rev(resolutions)))
})

test_that("generators come from DoE.base rather than decoded Yates codes", {
  expect_equal(
    DoE.base::generators("6-2.1", select.catlg = FrF2::catlg)[[1]],
    c("E=ABC", "F=ABD")
  )
})

test_that("a full factorial has every combination and aliases nothing", {
  design <- factorial_create(num_factors = 3, num_runs = 8)
  expect_equal(nrow(design$table), 8)
  expect_equal(design$notes, character())
  expect_snapshot(design)
})

test_that("a fractional factorial reports its resolution and generators", {
  expect_snapshot(factorial_create(num_factors = 6, num_runs = 16))
})

test_that("type selects among the catalog variants", {
  types <- factorial_get_types(6, 16)
  expect_gt(length(types), 1)
  first <- factorial_create(num_factors = 6, num_runs = 16, type = types[[1]])
  second <- factorial_create(num_factors = 6, num_runs = 16, type = types[[2]])
  expect_false(identical(first$notes, second$notes))
  # NULL takes the best one, which is the first.
  expect_equal(
    factorial_create(num_factors = 6, num_runs = 16)$notes,
    first$notes
  )
})

test_that("types are named by their label and carry catalog ids", {
  types <- factorial_get_types(6, 16)
  expect_true(all(types %in% names(FrF2::catlg)))
  expect_match(names(types)[1], "^Resolution ")
  # A full factorial has no variants, and callers must cope with that.
  expect_length(factorial_get_types(3, 8), 0)
})

test_that("an unknown type is rejected by name, not silently replaced", {
  # The old index-based argument would quietly select whatever sat at that
  # position when the size changed.
  expect_snapshot(error = TRUE, {
    factorial_create(num_factors = 6, num_runs = 16, type = "6-2.99")
    factorial_create(num_factors = 6, num_runs = 16, type = "8-3.1")
  })
})

test_that("default names cross from letters to names0 past the alphabet", {
  expect_equal(
    names(factorial_create(num_factors = 20, num_runs = 256)$table)[c(1, 20)],
    c("A", "T")
  )
  big <- names(factorial_create(num_factors = 30, num_runs = 64)$table)
  expect_equal(big[c(1, 30)], c("x01", "x30"))
  expect_false(any(big %in% LETTERS))
})

test_that("renaming factors adds a legend but keeps the alias letters", {
  plain <- factorial_create(num_factors = 6, num_runs = 16)
  renamed <- factorial_create(
    num_factors = 6,
    num_runs = 16,
    factor_names = rename_factors("Temp, Pressure", 6)
  )
  expect_equal(names(renamed$table)[1:2], c("Temp", "Pressure"))
  # The confounding itself stays written in FrF2's letters, unchanged ...
  confounding <- function(x) grep("^Two-factor", x, value = TRUE)
  expect_equal(confounding(renamed$notes), confounding(plain$notes))
  # ... with a legend added that maps those letters onto the new names. The
  # legend is absent when nothing has been renamed, since it would be identity.
  expect_match(renamed$notes[[1]], "^Factors: A=Temp, B=Pressure$")
  expect_length(grep("^Factors:", plain$notes), 0)
})

test_that("a large design reports aliasing without enumerating words", {
